using Astrea.BattleActions;
using UnityEngine;

namespace Astrea.GameElements;

[CreateAssetMenu(fileName = "EnemyActionLogic_RandomTarget", menuName = "Data/Battle/Logics/Enemy Action/Random Target")]
public class EnemyActionLogic_RandomTarget : EnemyActionLogic
{
	[Header("Units")]
	[SerializeField]
	private CurrentActiveUnits currentActiveUnits;

	public override void ActivateAction(BattleAction battleAction, int actionAmount, GameObject source)
	{
		base.ActivateAction(battleAction, actionAmount, source);
		GameObject gameObject = null;
		gameObject = GetNormalRandomTarget();
		if (actionAmount == EffectsValues.NO_VALUE)
		{
			battleAction.CastTarget(gameObject, source);
		}
		else
		{
			battleAction.CastTargetAmount(gameObject, actionAmount, source);
		}
	}

	private GameObject GetNormalRandomTarget()
	{
		return currentActiveUnits.GetCurrentActiveUnits().PickRandom();
	}
}
